9|import React, { useLayoutEffect, useRef } from 'react';
10|
11|import * as styles from './PageLayout.css';
12|
13|import type {
14|  PageLayoutConfig,
15|  PageLayoutProps,
16|  SpacingKey,
17|} from './PageLayout.types';
18|
19|const space = (key: SpacingKey) =>
20|  (tokens.spacing as Record<string, string>)[key] ?? '0px';
21|const px = (value: number) => `${value}px`;
22|// Data attributes take a boolean as present or absent.
23|const flag = (on: boolean) => (on ? '' : undefined);
24|
25|/** The grid's areas, columns and rows: the sidebar beside the main region, the header and footer above and below it. */
26|export function frameGrid(layout: PageLayoutConfig) {
27|  const fullWidth = layout.docksFirst === 'header';
28|
29|  const sidebars = ([['sidebar', layout.sidebar]] as const).filter(
30|    ([, sidebar]) => sidebar.needed,
31|  );
32|  const left = sidebars.filter(([, sidebar]) => sidebar.side === 'left');
33|  const right = sidebars.filter(([, sidebar]) => sidebar.side === 'right');
34|
35|  const stack = [
36|    layout.header.needed && 'header',
37|    'main',
38|    layout.footer.needed && 'footer',
39|  ].filter((area): area is string => Boolean(area));
40|
41|  const row = (area: string) =>
42|    area === 'main' || !fullWidth
43|      ? [...left.map(([name]) => name), area, ...right.map(([name]) => name)]
44|      : [...left, [area], ...right].map(() => area);
45|
46|  return {
47|    areas: stack.map((area) => `"${row(area).join(' ')}"`).join(' '),
48|    columns: [
49|      ...left.map(([, sidebar]) => px(sidebar.widthPx)),
50|      'minmax(0, 1fr)',
51|      ...right.map(([, sidebar]) => px(sidebar.widthPx)),
52|    ].join(' '),
53|    rows: stack.map((area) => (area === 'main' ? '1fr' : 'auto')).join(' '),
54|  };
55|}
56|
57|/**
58| * A frame from the theme's page layout: header, sidebar and footer around
59| * the page's container. The layout's sizes, sticking and separations are its
60| * own; the slots hold only what sits in each bar. The header has three: its
61| * left and right ends and its center. The sidebar is a
62| * SidebarMenu: `sidebar` holds its rows, `sidebarHeader` and `sidebarFooter`
63| * what stays fixed above and below them.
64| *
65| * @invalidAlternative main
66| */
67|export const PageLayout = ({
68|  layout,
69|  kind,
70|  headerLeft,
71|  header,
72|  headerRight,
73|  sidebarHeader,
74|  sidebar,
75|  sidebarFooter,
76|  footer,
77|  children,
78|}: PageLayoutProps) => {
79|  const scrollMain = kind === 'app';
80|  const rootRef = useRef<HTMLDivElement>(null);
81|  const headerRef = useRef<HTMLElement>(null);
82|
83|  const grid = frameGrid(layout);
84|  const { main } = layout;
85|  const overlay = layout.header.needed && layout.header.overlay;
86|
87|  const container = (
88|    <div
89|      data-ds=""
90|      data-slot="container"
91|      data-container={main.container}
92|      data-separation={main.separation}
93|      // A SectionGroup whose sections sit the kind's fixed gap apart.
94|      className={classNames(
95|        sectionGroup,
96|        scrollMain ? 'flex-col-gap-6' : 'flex-col-gap-9',
97|        styles.container,
98|      )}
99|      style={assignInlineVars({
100|        [styles.maxWidth]: px(main.maxWidthPx),
101|      })}
102|    >
103|      {children}
104|    </div>
105|  );
106|
107|  // Nothing outside the main region scrolls when it scrolls on its own, so nothing needs to stick.
108|  const sticky = (on: boolean) => !scrollMain && on;
109|
110|  // A header sized by its content has a height only once rendered.
111|  useLayoutEffect(() => {
112|    const element = headerRef.current;
113|    const root = rootRef.current;
114|    if (!element || !root) return;
115|    const observer = new ResizeObserver(() =>
116|      setElementVars(root, {
117|        [styles.headerHeight]: px(element.offsetHeight),
118|      }),
119|    );
120|    observer.observe(element);
121|    return () => observer.disconnect();
122|  }, []);
123|
124|  return (
125|    <div
126|      ref={rootRef}
127|      data-ds=""
128|      data-overlay={flag(overlay)}
129|      data-scroll-main={flag(scrollMain)}
130|      className={styles.root}
131|      style={assignInlineVars({
132|        [styles.areas]: grid.areas,
133|        [styles.columns]: grid.columns,
134|        [styles.rows]: grid.rows,
135|        [styles.headerHeight]: px(0),
136|      })}
137|    >
138|      {layout.header.needed && (
139|        <header
140|          ref={headerRef}
141|          data-ds=""
142|          data-sticky={flag(sticky(layout.header.sticky))}
143|          data-overlay={flag(overlay)}
144|          data-separation={layout.header.separation}
145|          className={styles.header}
146|          style={assignInlineVars({
147|            [styles.padding]: space(layout.header.padding),
148|            [styles.gap]: space(layout.header.gap),
149|          })}
150|        >
151|          <div data-ds="" data-slot="header-left" className={styles.headerLeft}>
152|            {headerLeft}
153|          </div>
154|          <div data-ds="" data-slot="header-center" className={styles.headerCenter}>
155|            {header}
156|          </div>
157|          <div data-ds="" data-slot="header-right" className={styles.headerRight}>
158|            {headerRight}
159|          </div>
160|        </header>
161|      )}
162|      {layout.sidebar.needed && (
163|        <SidebarMenu
164|          aria-label="Sidebar"
165|          header={sidebarHeader}
166|          footer={sidebarFooter}
167|          data-side={layout.sidebar.side}
168|          data-separation={layout.sidebar.separation}
169|          className={styles.sidebar}
170|          style={{ gridArea: 'sidebar' }}
171|        >
172|          {sidebar}
173|        </SidebarMenu>
174|      )}
175|      <main
176|        data-ds=""
177|        data-panel={flag(main.separation !== 'none')}
178|        className={classNames(styles.main, scrollMain && 'flex-col-gap-0')}
179|        style={assignInlineVars({ [styles.padding]: space(main.padding) })}
180|      >
181|        {scrollMain ? (
182|          <FlexScrollArea
183|            // The page keeps the region's width: wide content, like a table, scrolls sideways itself.
184|            orientation="vertical"
185|          >
186|            {container}
187|          </FlexScrollArea>
188|        ) : (
189|          container
190|        )}
191|      </main>
192|      {layout.footer.needed && (
193|        <footer
194|          data-ds=""
195|          data-separation={layout.footer.separation}
196|          // A site's footer stacks its lines; an app's holds one row.
197|          data-lines={flag('content' in layout.footer)}
198|          className={styles.footer}
199|          style={assignInlineVars({
200|            [styles.padding]: space(layout.footer.padding),
201|            [styles.gap]: space(layout.footer.gap),
202|          })}
203|        >
204|          {footer}
205|        </footer>
206|      )}
207|    </div>
208|  );
209|};

