3|import { signOut, useCurrentUser } from '@app/entities/auth';
4|import { classNames } from '@packages/styles/classNames';
5|import { Avatar } from '@packages/ui/Avatar';
6|import { Button, PlainButton } from '@packages/ui/Button';
7|import { Dropdown } from '@packages/ui/Dropdown';
8|import { Truncate } from '@packages/ui/Truncate';
9|import { LogOut } from 'lucide-react';
10|import React from 'react';
11|
12|import { NextLink } from '../NextLink';
13|
14|import type { UserMenuProps } from './UserMenu.types';
15|
16|/**
17| * The account in a header or a sidebar, from the app's session. Signed in, it
18| * shows the user's avatar and name, and opens a menu: the name, the rows
19| * passed as children, then Sign out, which signs out. Signed out, it shows a
20| * Sign in button. It shows nothing while the saved session is read.
21| */
22|export const UserMenu = ({
23|  placement,
24|  signInHref,
25|  children,
26|  variant,
27|  size,
28|  look,
29|  className,
30|}: UserMenuProps) => {
31|  const session = useCurrentUser();
32|  if (session === undefined) return null;
33|
34|  if (session === null)
35|    return (
36|      <Button
37|        as={NextLink}
38|        href={signInHref}
39|        // Marked, so the rendered checks find the account in every frame.
40|        data-user-menu=""
41|        variant={variant}
42|        size={size}
43|        look={look}
44|        className={className}
45|      >
46|        Sign in
47|      </Button>
48|    );
49|
50|  const inSidebar = placement === 'sidebar';
51|  // The session knows the user by email.
52|  const name = session.email;
53|  return (
54|    <Dropdown
55|      side={inSidebar ? 'right' : 'bottom'}
56|      menu={
57|        <>
58|          <Dropdown.Group label={name} />
59|          {children}
60|          <Dropdown.Separator />
61|          <Dropdown.Item leftIcon={<LogOut />} onSelect={signOut}>
62|            Sign out
63|          </Dropdown.Item>
64|        </>
65|      }
66|    >
67|      <PlainButton
68|        aria-label={`Account menu for ${name}`}
69|        data-user-menu=""
70|        className={className}
71|      >
72|        <span
73|          data-ds=""
74|          className={classNames(
75|            'flex-row-gap-2 items-center',
76|            inSidebar && 'w-full',
77|          )}
78|        >
79|          <Avatar
80|            size="sm" // One line high, so the header bar and the sidebar row keep their height.
81|            name={name}
82|          />
83|          <Truncate>{name}</Truncate>
84|        </span>
85|      </PlainButton>
86|    </Dropdown>
87|  );
88|};

